public class MBTOBYTE {
/**
     * Converts MB to bytes.
     * 
     * @param mbytes The MB to convert.
     * @return The converted result.
     */

    private static long mbTobyte(final long mbytes)
    {
        final int MB_TO_BYTE = 1048576;
        return mbytes * MB_TO_BYTE;
    }
},1

public class ISTOKENEXPIRED {
/**
     * Checks if the token is expired.
     * 
     * @param tokenExpiryTime The token expiration time.
     * @return A boolean indicating if the token is expired.
     */
    public static boolean istokenexpired(final long tokenExpiryTime)
    {
        return tokenExpiryTime < System.currentTimeMillis();
    }
},1

public class DISTANCESQ {
/**
     * Returns the square of the distance between two points.
     *
     * @param x1 the X coordinate of the first specified point
     * @param y1 the Y coordinate of the first specified point
     * @param x2 the X coordinate of the second specified point
     * @param y2 the Y coordinate of the second specified point
     * @return the square of the distance between the two
     * sets of specified coordinates.
     * @since 1.2
     */
    public static double distancesq(double x1, double y1,
                                    double x2, double y2)
    {
        x1 -= x2;
        y1 -= y2;
        return (x1 * x1 + y1 * y1);
    }
},1

public class DISTANCE {
/**
     * Returns the distance between two points.
     *
     * @param x1 the X coordinate of the first specified point
     * @param y1 the Y coordinate of the first specified point
     * @param x2 the X coordinate of the second specified point
     * @param y2 the Y coordinate of the second specified point
     * @return the distance between the two sets of specified
     * coordinates.
     * @since 1.2
     */
    public static double distance(double x1, double y1,
                                  double x2, double y2)
    {
        x1 -= x2;
        y1 -= y2;
        return Math.sqrt(x1 * x1 + y1 * y1);
    }
},1

public class FONTSIZE {
/**
     * Caclulates the font size in pixels given the font size in points and
     * the resolution (dots-per-inch)
     *
     * @param pt Font size in points (1 in = 72 points)
     * @param dpi Resolution in dots-per-inch (pixels-per-inch)
     * @return the font-size in pixels
     */
    private int fontSize(int pt, int dpi) {
        return (int) ( ((float) pt) / 72f * ((float) dpi) );
    }
},1

public class TOALFRESCOLOCKTIMEOUT {
/**
     * Convert FrontPageExtension lock timeout to Alfresco lock timeout. FrontPageExtension timeout is number of minutes, but Alfresco timeout is number of seconds.
     * 
     * @param timeout FrontPageExtension lock timeout
     * @return Alfresco lock timeout
     */
    public static int toalfrescolocktimeout(int timeout)
    {
        return timeout * 60;
    }
},1

public class RANDOMNUMBER {
/**
     * @param min
     * @param max
     * @return
     */
    private int randomNumber (int min, int max)
    {
        return min + (int)(Math.random() * ((max - min) + 1));
    }
