public class EQUALS {
/**
	 * Compare if two floats are equals within the given delta tolerance.
	 * 
	 * @param f1
	 *            A float
	 * @param f2
	 *            Another float
	 * @param delta
	 *            The delta tolerance.
	 * @return True if they are equal, false if not.
	 */
	public static boolean equals(float f1, float f2, float delta) {
		return Math.abs(f1 - f2) <= delta;
	}
},1

