public class GETMULTIPLE {
/**
	 * @param dec
	 * @return
	 */
	private static double getMultiple( int dec )
	{
		double multiple = 1;
		if ( dec >= 0 )
		{
			for ( int i = 0; i < dec; i++ )
			{
				multiple *= 10;
			}
		}
		else
		{
			double adjustment = 1;
			for( int i = dec; i < 0; i++ )
			{
				multiple *= 0.1;
				adjustment *= 10;
			}
			multiple = Math.round( multiple * adjustment ) / adjustment; 
		}
		return multiple;
	}
},4

public class PERCENT {
/**
	 * @param denom
	 *            the denominator
	 * @param num
	 *            the numerator
	 * @param valueIfZero
	 * 			  The percent value to return if the numerator is zero. The default is null.
	 * @return the percentage of two numbers
	 */
	static double percent(double denom, double num, double valueIfZero)
	{
		if(num == 0d)
		{
			return valueIfZero;
		}
		if(denom == 0d)
		{
			throw ( new IllegalArgumentException(
					"There exists illegal parameter:" + denom) );
		}

		return ( num / denom ) * 100;
	}
},3

