public class ZETASTATIC {
/**
	 * Compute the zeta constant needed for the distribution. Do this
	 * incrementally for a distribution that has n items now but used to have st
	 * items. Use the zipfian constant theta. Remember the new value of n so
	 * that if we change the itemcount, we'll know to recompute zeta.
	 * 
	 * @param st
	 *            The number of items used to compute the last initialsum
	 * @param n
	 *            The number of items to compute zeta over.
	 * @param theta
	 *            The zipfian constant.
	 * @param initialsum
	 *            The value of zeta we are computing incrementally from.
	 */
	static double zetastatic(long st, long n, double theta, double initialsum) {
		double sum = initialsum;
		for (long i = st; i < n; i++) {

			sum += 1 / (Math.pow(i + 1, theta));
		}

		// System.out.println("countforzeta="+countforzeta);

		return sum;
	}
},2

public class REHASH {
/**
     * Applies a supplemental hash function to a given hash code, which defends
     * against poor quality hash functions. This is critical when the concurrent
     * hash map uses power-of-two length hash tables, that otherwise encounter
     * collisions for hash codes that do not differ in lower or upper bits.
     * 
     * @param h
     *        hash code
     */
    private static int rehash(int h) {
        // Spread bits to regularize both segment and index locations,
        // using variant of single-word Wang/Jenkins hash.
        h += (h << 15) ^ 0xffffcd7d;
        h ^= (h >>> 10);
        h += (h << 3);
        h ^= (h >>> 6);
        h += (h << 2) + (h << 14);
        return h ^ (h >>> 16);
    }
},1

