public class TOSRGB {
/**
	 * Input is assumed to be scaled 0-1
	 */
	public double tosrgb(double v)
		{
		double a=0.055;
		if(v<0.0031308)
			return 12.92*v;
		else
			return (1+a)*Math.pow(v,1/2.4)-a;
		}
},2

public class TOXYZ {
/**
	 * Input is assumed to be scaled 0-1
	 */
	public double toxyz(double v)
		{
		double a=0.055;
		if(v<0.04045)
			return v/12.92;
		else
			return Math.pow((v+a)/a,2.4);
		}
},2

