public class CEILPOWER2 {
/**
	 * Ceil to nearest 2^
	 */
	public static int ceilpower2(int s)
		{
		if(s>1024)
			{
			double log2=Math.log(2);
			double x=Math.ceil(Math.log(s)/log2);
			int v=(int)Math.exp(Math.log(2)*x);
			System.out.println("ceilpow2 "+s+" => "+v);
			return v;
			}
		else if(s>512) return 1024;
		else if(s>256) return 512;
		else if(s>128) return 256;
		else if(s>64) return 128;
		else if(s>32) return 64;
		else if(s>16) return 32;
		else if(s>8) return 16;
		else if(s>4) return 8;
		else return 4;
		}
},10

public class ISINSIDETRIANGLE {
/**
	 * Check if the point p is inside the triangle
	 */
	private static boolean isInsideTriangle(double Ax, double Ay,
      double Bx, double By,
      double Cx, double Cy,
      double Px, double Py)

		{
		double ax, ay, bx, by, cx, cy, apx, apy, bpx, bpy, cpx, cpy;
		double cCROSSap, bCROSScp, aCROSSbp;

		ax = Cx - Bx;  ay = Cy - By;
		bx = Ax - Cx;  by = Ay - Cy;
		cx = Bx - Ax;  cy = By - Ay;
		apx= Px - Ax;  apy= Py - Ay;
		bpx= Px - Bx;  bpy= Py - By;
		cpx= Px - Cx;  cpy= Py - Cy;

		aCROSSbp = ax*bpy - ay*bpx;
		cCROSSap = cx*apy - cy*apx;
		bCROSScp = bx*cpy - by*cpx;

		return ((aCROSSbp >= 0.0f) && (bCROSScp >= 0.0f) && (cCROSSap >= 0.0f));
		}
},3

public class TRIANGLEAREAUSINGSIDES {
/**
	 * Calculate area of triangle given lengths of sides.
	 * Uses Heron's formula.
	 */
	public static double triangleareausingsides(double a, double b, double c)
		{
		double s=(a+b+c)/2;
		return Math.sqrt(s*(s-a)*(s-b)*(s-c));
		}
},1

public class INTERPOLATELINEAR {
/**
	 * Linear interpolation: Given (x1,y1) and (x2,y2), find y in (x,y)
	 */
	public static double interpolatelinear(double x1, double y1, double x2, double y2, double x)
		{
		double s=(x-x1)/(x2-x1);
		return s*y2+(1.0-s)*y1;
		}
},1

public class UNBIASEDVARIANCE {
/**
	 * Calculate unbiased sample variance
	 * @param sum		Sum X
	 * @param sum2	Sum X^2
	 * @param n			Number of samples
	 */
	public static double unbiasedvariance(double sum, double sum2, int n)
		{
		int n1=n-1;
		return sum2/n1 - sum*sum/(n1*n);
		}
},1

public class BIASEDVARIANCE {
/**
	 * Biased sample variance i.e. the plug-in estimate. Equals 0 for a single sample
	 * @param sumx	Sum X
	 * @param sumxx	Sum X^2
	 * @param n			Number of samples
	 */
	public static double biasedvariance(double sumx, double sumxx, double n)
		{
		return (sumxx - sumx*sumx/n)/n;
//		return sum2/n - sum*sum/(n*n);
		}
},1

public class BIASEDCOVARIANCE {
/**
	 * Biased sample covariance i.e. the plug-in estimate. Equals 0 for a single sample.
	 * @param sumx  sum X
	 * @param sumy  sum Y
	 * @param sumxy sum XY
	 * @param n     Number of samples
	 */
	public static double biasedcovariance(double sumx, double sumy, double sumxy, double n)
		{
//		return (sumxy - 2*sumx*sumy/n + sumx*sumy/n)/n;
		return (sumxy - sumx*sumy/n)/n;
		}
},1

