public class MAXALLINT {
/**
	 * Get the maximum of a list
	 */
	public static int maxallint(int... v)
		{
		int r=v[0];
		for(int i=1;i<v.length;i++)
			if(v[i]>r)
				r=v[i];
		return r;
		}
