public class TOASCII {
/**
   * Converts all bytes into the ascii printable range (32 >= 126),
   */
  static byte toAscii(byte b) {
    b &= 0x7f;
    if (b >= 0 && b < 32)
      return ' ';
    if (b == 127)
      return ' ';
    if (b == '\n')
      return ' ';
    return b;
  }
