public class INT2CHAR {
/**
     * Convert an integer to the respective character representation.
     * Used to generate Word Shape Type II.
     * @param n The number.
     * @return The respective character.
     */
    private char Int2Char(int n) {
        if (n == 0) {
            return '*';
        }
        if (n == 1) {
            return 'a';
        }
        if (n == 2) {
            return '#';
        }

        return ' ';
    }
},4

public class GETFROMCHAR {
/**
* Turns a char that encodes four bits in hexadecimal notation into a byte
*
* @param c the char to convert
*
*/
public static byte getfromchar(char c) {
  if (c <= '9') {
      return (byte) (c - '0');
  } else if (c <= 'F') {
      return (byte) (c - 'A' + 10);
  } else {
      return (byte) (c - 'a' + 10);
  }
}
},3

