public class ISNUMERICTYPESPECIFIER {
/**
    *  Returns true if the specified character is a valid type specifier
    *  for a numeric value.
    */

    public static boolean isnumerictypespecifier( char c, boolean isDecimal )
    {
        if( isDecimal )
        {
            switch( c )
            {
                case 'G':
                case 'g':
                case 'D':
                case 'd':
                case 'F':
                case 'f':
                    return true;
            }
        }
        else
        {
            switch( c )
            {
                case 'G':
                case 'g':
                case 'I':
                case 'i':
                case 'L':
                case 'l':
                    return true;
            }
        }

        return false;
    }
},4

