public class GETTSTATRANK {
/**
     * @param t thr T statistic value to convert into a roughly resembling it <code>short</code>
     * @return tStat ranks as follows:
     *         t =<  -9       -> rank: -10
     *         t in <-6, -9)  -> rank: -7
     *         t in <-3, -6)  -> rank: -4
     *         t in (-3,  0)  -> rank: -1
     *         t == 0         -> rank:  0
     *         t in ( 0,  3)  -> rank:  1
     *         t in < 3,  6)  -> rank:  4
     *         t in < 6,  9)  -> rank:  7
     *         t >=   9       -> rank:  10
     *         Note that the higher the absolute value of tStat (rank) the better the tStat.
     */
    private static short getTStatRank(float t) {
        // TODO: 4alf: what about NaN?
        if (t <= -9) {
            return -10;
        } else if (t <= -6) {
            return -7;
        } else if (t <= -3) {
            return -4;
        } else if (t < 0) {
            return -1;
        } else if (t == 0) {
            return 0;
        } else if (t < 3) {
            return 1;
        } else if (t < 6) {
            return 4;
        } else if (t < 9) {
            return 7;
        } else {
            return 10;
        }
    }
},9

public class GCD {
/**
   * Determines the greatest common divisor (GCD) of two integers.
   * 
   *  @param m the first integer
   *  @param n the second integer
   *  
   *  @return the greatest common divisor of m and n
   */
  public static int gcd(int m, int n) {
    if (m == 0 && n == 0)
      return 0;
    if (m < n) {
      int t = m;
      m = n;
      n = t;
    }
    int r = m % n;
    if (r == 0) {
      return n;
    } else {
      return gcd(n, r);
    }
  }
},5

