public class GETDOUBLE {
/**
   * Converts excel's internal RK format into a double value
   *
   * @param rk the rk number in bits
   * @return the double representation
   */
  public static double getdouble(int rk)
  {
    if ((rk & 0x02) != 0)
    {
      int intval = rk >> 2;

      double value = intval;
      if ((rk & 0x01) != 0)
      {
        value /= 100;
      }

      return value;
    }
    else
    {
      long valbits = (rk & 0xfffffffc);
      valbits <<= 32;
      double value = Double.longBitsToDouble(valbits);

      if ((rk & 0x01) != 0)
      {
        value /= 100;
      }

      return value;
    }
  }
},4

public class ROTLEFT15BIT {
/**
   * Rotate the value by 15 bits.  Thanks to Michael for this
   *
   * @param val
   * @param rotate
   * @return int
   */
  private int rotLeft15Bit(int val, int rotate)
  {
    val = val &0x7FFF;

    for(; rotate > 0; rotate--) 
    {
      if((val & 0x4000) != 0) 
      {
        val = ((val << 1) & 0x7FFF) + 1;
      }
      else
      {
        val = (val << 1) & 0x7FFF;
      }
    }

    return val;
  }
},3

public class INDEXPOSITIONSAREOK {
/**
	 * Given two integers, this method returns true if:
	 * no input equals -1 and indexOne is smaller or equals indexTwo.
	 * Usage: say you want to see what is in between two parenthesis
	 * signs in a string. You get the index of both these signs, and 
	 * by using this method, you can see if they are placed properly.
	 * ie not 'he (k', 	')he(' or 	'hej)'.
	 * @param indexOne the index of the sign which is supposed to come first.
	 * @param indexTwo the index of the sign which is supposed to come second.
	 * @return true if their positions are ok.
	 */
	private boolean indexPositionsAreOk(int indexOne, int indexTwo) {
		return (indexOne != -1) && (indexTwo != -1) && (indexOne <= indexTwo);
	}
