public class HEXDIGIT {
/**
	 * Convert a value 0-15 to an ASCII hex digit
	 */
	private byte hexDigit(int v) {
		if (v < 10)
			return (byte) (0x30 + v);
		else
			return (byte) (0x41 + v - 10);
	}
},2

public class FROMHEX {
/**
	 * Convert a hex representation of a byte to it's actual value
	 * 
	 * @param b
	 *            hex representation of a byte
	 * @return byte
	 */
	private byte fromHex(byte b) {
		if (b >= 48 && b <= 57)
			return (byte) (b - 48);
		if (b >= 65 && b <= 70)
			return (byte) (b - 65 + 10);
		if (b >= 97 && b <= 102)
			return (byte) (b - 97 + 10);

		return (byte) 0;
	}
},7

