public class PARSEBOOLEAN {
/**
	 * Parses the character value of 'Y' or 'N' into boolean value.
	 *
	 * @param value - the character to be parsed
	 * @return <code>true</code>, if value is 'Y', else <code>false</code>
	 */
	public boolean parseboolean(char value)
	{
		boolean flag = true;
		boolean boolValue = false;

		while(flag)
		{
			//parses 'Y' into 'true'
			if(value == 'Y' || value == 'y')
			{
				boolValue = true;
				flag = false;
			}

			//parses 'N' into 'false'
			else if(value == 'N' || value == 'n')
			{
				boolValue = false;
				flag = false;
			}

			//validates user input
			else
			{
				System.out.println("Invalid input. Enter (Y/N)");
			}
		}

		return boolValue;
	}
},6

public class CALCSTEPS {
/**
	 * @param start
	 * @param stop
	 * @param step
	 * @return number of steps to take
	 */
	public static int calcsteps(final double start, final double stop, final double step) {
		if (step > 0) {
