public class PDF {
/**
	 * probability density function
	 * 
	 * @param x
	 *            argument
	 * @param m
	 *            mean
	 * @param sd
	 *            standard deviation
	 * @return pdf at x
	 */
	public static double pdf(double x, double m, double sd) {
		double a = 1.0 / (Math.sqrt(2.0 * Math.PI) * sd);
		double b = -(x - m) * (x - m) / (2.0 * sd * sd);

		return a * Math.exp(b);
	}
