public class EASE {
/**
	 * A dumb easing function that moves the camera
	 * @param start the start point
	 * @param target the end point
	 * @return the amount to ease
	 */
	private float ease(float start, float target)
	{
		if (Math.abs(target - start) < 4)
			return target;

		if (target < start)
			return start - 2;

		return start + 2;
	}
},3

public class ROLLDICE {
/**
	 * Roll dice
	 * @param sides number of sides
	 * @param count the number of dice to roll
	 * @return the value of the die
	 */
	protected int rollDice(int sides, int count)
	{
		int value = 0;
		while (count-- > 0)
		{
			value += (int) (Math.random() * sides) + 1;
		}
		return value;
	}
},2

public class DEHEXCHAR {
/**
     * Get the hex value of a character (base16).
     * @param c A character between '0' and '9' or between 'A' and 'F' or
     * between 'a' and 'f'.
     * @return  An int between 0 and 15, or -1 if c was not a hex digit.
     */
    public static int dehexchar(char c) {
        if (c >= '0' && c <= '9') {
            return c - '0';
        }
        if (c >= 'A' && c <= 'F') {
            return c - ('A' - 10);
        }
        if (c >= 'a' && c <= 'f') {
            return c - ('a' - 10);
        }
        return -1;
    }
},7

public class CALCULATEHORIZONTALMARGIN {
/**
     * To account for negative margins
     */
    private int calculateHorizontalMargin( int prevMarginRight, int marginLeft ) 
    {
        int max = Math.max( prevMarginRight, marginLeft );
        int sum = prevMarginRight + marginLeft;
        if( sum < max ) {
            max += ( sum - max );
        }
        return max;
    }
},2

